#!/usr/bin/env python3
"""Inline circomlib2 (circomlib_buses) definitions into self-contained tests.

Every test under certifier_tests/ must compile on its own, without `-l`.
When a test needs circomlib2 templates, it declares them with a directive

    // @circomlib IsZero LessThan

and holds a block delimited by

    // ===== BEGIN circomlib (generated by tools/inline_circomlib.py) =====
    ...
    // ===== END circomlib =====

This tool fills that block with the VERBATIM definitions of the requested
templates plus everything they transitively use (templates, functions,
buses), copied from a checkout of iden3/circomlib at the commit whose hashes
are embedded in `-cbc` (constraint_generation/src/circomlib2_template_hashes.txt).
Since `-cbc` trusts a template by the hash of its own definition text (not by
file or path), the inlined copies are recognised exactly like the originals.

Usage:
    inline_circomlib.py --lib <circomlib>/circuits fill  [tests...]
    inline_circomlib.py --lib <circomlib>/circuits check [tests...]
    inline_circomlib.py --lib <circomlib>/circuits verify-hashes

`fill` rewrites the blocks, `check` fails if any block is stale, and
`verify-hashes` recomputes the hash of every template, function and bus under --lib with the
same normalisation as `certifier.rs` and compares it with the embedded table.
"""

import argparse
import hashlib
import pathlib
import re
import sys

HERE = pathlib.Path(__file__).resolve().parent
TESTS_ROOT = HERE.parent
HASH_TABLE = TESTS_ROOT.parent / "constraint_generation" / "src" / "circomlib2_template_hashes.txt"

BEGIN = "// ===== BEGIN circomlib (generated by tools/inline_circomlib.py) ====="
END = "// ===== END circomlib ====="
DIRECTIVE = re.compile(r"^//\s*@circomlib\s+(.*)$", re.M)

IDENT = re.compile(r"[A-Za-z_$][A-Za-z0-9_$]*")


# ---------------------------------------------------------------------------
# Lexing helpers
# ---------------------------------------------------------------------------

def mask_comments_and_strings(src):
    """Same length as src, with comments and string literals replaced by spaces
    (newlines kept), so offsets stay valid for brace matching."""
    out = list(src)
    i, n = 0, len(src)
    while i < n:
        c = src[i]
        if c == "/" and i + 1 < n and src[i + 1] == "/":
            while i < n and src[i] != "\n":
                out[i] = " "
                i += 1
        elif c == "/" and i + 1 < n and src[i + 1] == "*":
            j = src.find("*/", i + 2)
            j = n if j < 0 else j + 2
            for k in range(i, j):
                if src[k] != "\n":
                    out[k] = " "
            i = j
        elif c == '"':
            j = i + 1
            while j < n and src[j] != '"':
                j += 2 if src[j] == "\\" else 1
            j = min(j + 1, n)
            for k in range(i, j):
                if src[k] != "\n":
                    out[k] = " "
            i = j
        else:
            i += 1
    return "".join(out)


def normalize_definition(text):
    """Port of `normalize_definition` in certifier.rs."""
    out = []
    i, n = 0, len(text)
    pending_space = False
    while i < n:
        c = text[i]
        i += 1
        if c == "/" and i < n and text[i] == "/":
            while i < n:
                ch = text[i]
                i += 1
                if ch == "\n":
                    break
            is_space = True
        elif c == "/" and i < n and text[i] == "*":
            i += 1
            previous = " "
            while i < n:
                ch = text[i]
                i += 1
                if previous == "*" and ch == "/":
                    break
                previous = ch
            is_space = True
        else:
            is_space = c.isspace()
        if is_space:
            pending_space = True
        else:
            if pending_space and out:
                out.append(" ")
            pending_space = False
            out.append(c)
    return "".join(out)


def hash_definition(text):
    return hashlib.sha256(normalize_definition(text).encode()).hexdigest()


DEF_HEAD = re.compile(r"\b(template|function|bus)\s+(?:(?:parallel|custom)\s+)*([A-Za-z_$][A-Za-z0-9_$]*)")


def definitions(src):
    """[(kind, name, start, end)] for every top-level definition of src; the
    range runs from the keyword to the closing brace (inclusive)."""
    masked = mask_comments_and_strings(src)
    result = []
    pos, depth = 0, 0
    i, n = 0, len(masked)
    while i < n:
        c = masked[i]
        if c == "{":
            depth += 1
        elif c == "}":
            depth -= 1
        elif depth == 0:
            m = DEF_HEAD.match(masked, i)
            if m and (i == 0 or not (masked[i - 1].isalnum() or masked[i - 1] == "_")):
                brace = masked.find("{", m.end())
                d, j = 0, brace
                while j < n:
                    if masked[j] == "{":
                        d += 1
                    elif masked[j] == "}":
                        d -= 1
                        if d == 0:
                            break
                    j += 1
                result.append((m.group(1), m.group(2), i, j + 1))
                i = j + 1
                continue
        i += 1
    return result


INCLUDE = re.compile(r'^\s*include\s+"([^"]+)"', re.M)


# ---------------------------------------------------------------------------
# Library index
# ---------------------------------------------------------------------------

class Library:
    def __init__(self, root):
        self.root = pathlib.Path(root).resolve()
        self.files = {}      # rel path -> source
        self.defs = {}       # name -> [(rel, kind, text)]
        self.includes = {}   # rel -> [rel]
        for path in sorted(self.root.rglob("*.circom")):
            rel = path.relative_to(self.root).as_posix()
            src = path.read_text()
            self.files[rel] = src
            for kind, name, s, e in definitions(src):
                self.defs.setdefault(name, []).append((rel, kind, src[s:e]))
            incs = []
            for inc in INCLUDE.findall(src):
                target = (path.parent / inc).resolve()
                if target.is_file():
                    incs.append(target.relative_to(self.root).as_posix())
            self.includes[rel] = incs

    def include_closure(self, rel):
        seen, order = {rel}, [rel]
        k = 0
        while k < len(order):
            for nxt in self.includes.get(order[k], []):
                if nxt not in seen:
                    seen.add(nxt)
                    order.append(nxt)
            k += 1
        return order

    def resolve(self, name, from_rel=None):
        cands = self.defs.get(name, [])
        if not cands:
            return None
        if from_rel is not None:
            for rel in self.include_closure(from_rel):
                for cand in cands:
                    if cand[0] == rel:
                        return cand
        if len(cands) > 1 and from_rel is None:
            raise SystemExit(
                f"ambiguous circomlib name {name!r} (in {[c[0] for c in cands]}); "
                f"write it as file.circom:{name}"
            )
        return cands[0]

    def closure(self, requested):
        """Transitive closure of definitions used by the requested names.
        A name written as `-Name` is left out of the closure (the test
        provides its own, e.g. a tampered copy)."""
        excluded = {r[1:] for r in requested if r.startswith("-")}
        requested = [r for r in requested if not r.startswith("-")]
        chosen = {}  # (rel, name) -> (kind, text)
        work = []
        for req in requested:
            if ":" in req:
                rel, name = req.split(":", 1)
                cand = next((c for c in self.defs.get(name, []) if c[0] == rel), None)
            else:
                name, cand = req, self.resolve(req)
            if cand is None:
                raise SystemExit(f"unknown circomlib definition {req!r}")
            work.append((name, cand))
        while work:
            name, (rel, kind, text) = work.pop()
            if (rel, name) in chosen:
                continue
            chosen[(rel, name)] = (kind, text)
            masked = mask_comments_and_strings(text)
            # skip the definition's own name
            body = masked[masked.find(name) + len(name):]
            for ident in set(IDENT.findall(body)):
                if ident in self.defs and ident not in excluded:
                    cand = self.resolve(ident, rel)
                    if cand is not None and (cand[0], ident) not in chosen:
                        work.append((ident, cand))
        names = [n for (_, n) in chosen]
        dup = {n for n in names if names.count(n) > 1}
        if dup:
            raise SystemExit(f"closure needs two definitions with the same name: {sorted(dup)}")
        return chosen

    def render(self, requested):
        chosen = self.closure(requested)
        order = []
        for (rel, name), (kind, text) in chosen.items():
            pos = self.files[rel].find(text)
            order.append((rel, pos, name, kind, text))
        order.sort()
        lines = [BEGIN,
                 "// Verbatim from iden3/circomlib, branch circomlib_buses, commit aef239c",
                 "// (the snapshot embedded in -cbc). Do not edit by hand: -cbc trusts these",
                 "// templates by the hash of their definition text."]
        current = None
        for rel, _, name, kind, text in order:
            if rel != current:
                lines.append("")
                lines.append(f"// ---- circuits/{rel}")
                current = rel
            lines.append("")
            lines.append(text)
        lines.append("")
        lines.append(END)
        return "\n".join(lines)


# ---------------------------------------------------------------------------
# Commands
# ---------------------------------------------------------------------------

def test_files(args):
    if args.tests:
        return [pathlib.Path(t) for t in args.tests]
    return sorted(p for p in TESTS_ROOT.rglob("*.circom") if "tools" not in p.parts)


def regenerate(lib, path):
    src = path.read_text()
    m = DIRECTIVE.search(src)
    if not m:
        return src, None
    requested = m.group(1).split()
    block = lib.render(requested)
    if BEGIN in src:
        start = src.index(BEGIN)
        end = src.index(END, start) + len(END)
        new = src[:start] + block + src[end:]
    else:
        # circom wants every definition before `component main`
        main = re.search(r"^component\s+main\b", src, re.M)
        if main is None:
            new = src.rstrip("\n") + "\n\n" + block + "\n"
        else:
            new = src[:main.start()] + block + "\n\n" + src[main.start():]
    return new, requested


def table_key(kind, name):
    """Key used by the embedded table: `Name` for templates, `function:name`
    and `bus:Name` for the rest (format v2)."""
    return name if kind == "template" else f"{kind}:{name}"


def load_known():
    known = set()
    for line in HASH_TABLE.read_text().splitlines():
        if line.strip() and not line.startswith("#"):
            h, loc = line.split(None, 1)
            known.add((loc.rsplit("::", 1)[1], h))
    return known


def cmd_fill(lib, args, check_only):
    known = load_known()
    stale = 0
    for path in test_files(args):
        new, requested = regenerate(lib, path)
        if requested is None:
            continue
        # every inlined template must hash to an embedded entry
        block = new[new.index(BEGIN):new.index(END)]
        for kind, name, s, e in definitions(block):
            if (table_key(kind, name), hash_definition(block[s:e])) not in known:
                print(f"WARNING {path}: inlined {kind} {name} does not match the embedded hash table")
        if new != path.read_text():
            if check_only:
                print(f"STALE   {path}")
                stale += 1
            else:
                path.write_text(new)
                print(f"filled  {path}")
    return 1 if stale else 0


def cmd_verify(lib):
    known = load_known()
    total = bad = 0
    for rel, src in lib.files.items():
        for kind, name, s, e in definitions(src):
            total += 1
            if (table_key(kind, name), hash_definition(src[s:e])) not in known:
                bad += 1
                print(f"MISMATCH circuits/{rel}::{table_key(kind, name)}")
    print(f"{total - bad}/{total} templates/functions/buses match the embedded table ({len(known)} entries)")
    return 1 if bad else 0


def main():
    ap = argparse.ArgumentParser(description=__doc__, formatter_class=argparse.RawDescriptionHelpFormatter)
    ap.add_argument("--lib", required=True, help="circomlib checkout's circuits/ directory")
    ap.add_argument("command", choices=["fill", "check", "verify-hashes"])
    ap.add_argument("tests", nargs="*")
    args = ap.parse_args()
    lib = Library(args.lib)
    if args.command == "verify-hashes":
        sys.exit(cmd_verify(lib))
    sys.exit(cmd_fill(lib, args, args.command == "check"))


if __name__ == "__main__":
    main()
